83	                $relationship = $table?->getRelationship();
84	
85	                $translatableContentDriver = $livewire->makeFilamentTranslatableContentDriver();
86	
87	                if ($relationship instanceof BelongsToMany) {
88	                    $pivot = $record->getRelationValue($relationship->getPivotAccessor());
89	
90	                    $pivotColumns = $relationship->getPivotColumns();
91	                    $pivotData = Arr::only($data, $pivotColumns);
92	
93	                    if (count($pivotColumns)) {
94	                        if ($translatableContentDriver) {
95	                            $translatableContentDriver->updateRecord($pivot, $pivotData);
96	                        } else {
97	                            $pivot->update($pivotData);
98	                        }
99	                    }
100	
101	                    $data = Arr::except($data, $pivotColumns);
102	                }
103	
104	                if ($translatableContentDriver) {
105	                    $translatableContentDriver->updateRecord($record, $data);
106	                } else {
107	                    $record->update($data);
108	                }
109	            });
110	
111	            $this->success();
112	        });
113	    }
